from typing import Dict

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.bts.cloud_bts import CloudBts
from taf.rfrl.procedures.resources.python.bts.components.du.du import Du
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_info, pretty_log
from taf.rfrl.procedures.resources.python.timer.stopwatch import Stopwatch


def kpi_52a_auto_cloud_du_reset_downtime(testing_env: TestingEnv, expected_dus_downtimes: Dict[str, int]):
    """
    Based on:
    QC Test ID: 22796
    QC Test Name: CB012667_SR_A_04_Site_reset_duration_KPI1a_with_CB012667_for_benchmark

    Should report to:
    QC Test ID: 22796
    QC Test Name: CB012667_SR_A_04_Site_reset_duration_KPI1a_with_CB012667_for_benchmark

    Tested KPI: OM_GEN_SFS_PERF_CAP.20923

    :param testing_env: testing environment prepared for this test case
    :param expected_dus_downtimes: expected downtime values (in seconds) after reset for each DU identified by its name;
                                   DU name can be taken from "NRDU ID" field of DU details in CU WebEM;
                                   i.e. {'NRDU-1': 300,
                                         'NRDU-2': 360}
    """
    bts = testing_env.btss[0]
    stopwatch = testing_env.stopwatch
    errors = testing_env.errors

    _check_dus_names(bts, expected_dus_downtimes)

    for du in bts.dus:
        if du.name in expected_dus_downtimes:
            try:
                _allow_alarms_related_to_resetting_du(du)
                _trigger_du_reset(du)
                _start_measuring_time(stopwatch)
                _wait_for_last_cell_up(du)
                _stop_measuring_time(stopwatch)
                _check_du_downtime(du, stopwatch, expected_dus_downtimes)
                _disallow_alarms_related_to_resetting_du(du)
            except ResultError as exc:
                errors.add_from_exception(exc)

    errors.check()


def teardown_for_kpi_52a_auto_cloud_du_reset_downtime(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    bts.dus.check_state_on_all(state='on_air',
                               timeout=600)


def _check_dus_names(bts: CloudBts, expected_dus_downtimes: Dict[str, int]):
    bts.dus.check_if_names_exist(list(expected_dus_downtimes.keys()))


def _allow_alarms_related_to_resetting_du(du: Du):
    du.allow_alarm(fault_id='4592',
                   fault_name='BTS Reset Cause')
    du.cu.allow_alarm(fault_id='7104',
                      fault_name='Matching ServedCell not found over F1-C')


def _trigger_du_reset(du: Du):
    du.reset()
    du.check_if_unreachable(timeout=60)


@pretty_log
def _start_measuring_time(stopwatch: Stopwatch):
    log_info('Starting time measurement', to_console=True)
    stopwatch.start()


def _wait_for_last_cell_up(du: Du):
    du.check_if_reachable(delay=30, timeout=300)
    du.cells.check_state_on_all(state='online',
                                timeout=600)


@pretty_log
def _stop_measuring_time(stopwatch: Stopwatch):
    log_info('Stopping time measurement', to_console=True)
    stopwatch.stop()


@pretty_log
def _check_du_downtime(du: Du, stopwatch: Stopwatch, expected_dus_downtimes):
    measured_downtime = stopwatch.get_elapsed_seconds()
    expected_downtime = expected_dus_downtimes[du.name]
    downtime_msg = f'Time between first cell down and last cell up after DU reset (KPI#52a) on {du.name} was {measured_downtime}s'

    if measured_downtime > expected_downtime:
        error_msg = downtime_msg + f', expected {expected_downtime}s or less'
        raise ResultError(error_msg)
    else:
        log_info(downtime_msg, to_console=True)


def _disallow_alarms_related_to_resetting_du(du: Du):
    du.disallow_alarm(fault_id='4592',
                      fault_name='BTS Reset Cause')
    du.cu.disallow_alarm(fault_id='7104',
                         fault_name='Matching ServedCell not found over F1-C')
